\set ON_ERROR_STOP on
\connect muzhe_chuzhong
BEGIN;
CREATE TEMP TABLE teacher_bio_extensions (id text PRIMARY KEY, name text NOT NULL, extension text NOT NULL) ON COMMIT DROP;
DO $$ BEGIN
  IF (SELECT count(*) FROM teacher_bio_extensions) <> 31 THEN RAISE EXCEPTION '初中部扩写数量不是31'; END IF;
  IF EXISTS (SELECT 1 FROM teacher_bio_extensions d LEFT JOIN "Teacher" t ON t.id = d.id WHERE t.id IS NULL OR t.name <> d.name OR char_length(t.bio) NOT BETWEEN 200 AND 300) THEN RAISE EXCEPTION '初中部教师身份或原简介长度校验失败'; END IF;
END $$;
UPDATE "Teacher" t SET bio = t.bio || d.extension FROM teacher_bio_extensions d WHERE t.id = d.id;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM teacher_bio_extensions d JOIN "Teacher" t ON t.id = d.id WHERE char_length(t.bio) NOT BETWEEN 360 AND 450) THEN RAISE EXCEPTION '初中部扩写后简介不在360至450字之间'; END IF;
END $$;
SELECT '初中部' AS division, count(*) AS updated, min(char_length(t.bio)) AS shortest, max(char_length(t.bio)) AS longest FROM "Teacher" t JOIN teacher_bio_extensions d ON d.id = t.id;
COMMIT;

\connect muzhe_gaozhong
BEGIN;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM "Teacher" WHERE id = 'cmqgmp4a20004508l3ug1k1e9' AND name = '李元林' AND char_length(bio) BETWEEN 200 AND 300) THEN RAISE EXCEPTION '高中部教师身份或原简介长度校验失败'; END IF;
END $$;
UPDATE "Teacher" SET bio = bio || '高中阶段的课堂会更强调知识之间的纵向联系。例如讲函数时，先把图像、解析式和变化趋势放在一起理解；讲物理时，先还原过程，再决定使用何种规律。面对综合题，可让学生先独立提出解题方案，教师再通过追问帮助其发现遗漏的条件，而不是直接替学生完成推导。讲评时比较不同解法的适用范围，训练审题、表达与复核三个环节，力求让学生逐步适应新题。' WHERE id = 'cmqgmp4a20004508l3ug1k1e9' AND name = '李元林';
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "Teacher" WHERE id = 'cmqgmp4a20004508l3ug1k1e9' AND char_length(bio) NOT BETWEEN 360 AND 450) THEN RAISE EXCEPTION '高中部扩写后简介不在360至450字之间'; END IF;
END $$;
SELECT '高中部' AS division, count(*) AS updated, min(char_length(bio)) AS shortest, max(char_length(bio)) AS longest FROM "Teacher" WHERE id = 'cmqgmp4a20004508l3ug1k1e9';
COMMIT;
