INSERT INTO teacher_bio_extensions (id, name, extension) VALUES
('cmp8e9dd0000c2m5evupootus','任文涛','在具体讲题时，更适合从生活或技术场景引出问题，再把题目条件整理成图示、表格或等量关系。遇到学生答对但说不清理由的情况，会把重点放在“为什么这一步成立”上。练习按基础识别、独立推导和综合应用逐层推进，课后优先回看同类错误是否再次出现，而不是单纯增加刷题量。这样的安排旨在帮助学生把零散的理科知识连接起来。'),
('cmrc04ke801xenroplfoinnjl','任紫莹','课堂表达力求清楚、节奏分明。英语部分可以通过短句复述、语境替换检验词汇是否真正会用；物理和化学部分则先让学生描述观察到的现象，再讨论对应规律。对跨学科授课尤其要区分各科不同的思考方式，不把所有问题都变成背公式。练习结束后留下可执行的小目标，便于学生下一次课检验自己是否进步。'),
('cmsfsmp3l0g0wrx2r2e1xr7sj','张佳涵','讲解偏重结构化拆题：先标出已知量、未知量和隐含限制，再决定需要哪一个模型。对于物理图像题，会让学生先用语言解释曲线变化，再进入计算；对于数学综合题，提醒学生写出关键转化依据。课堂不急于给出标准答案，而是通过追问找到学生卡住的具体环节，再用一道相近但条件变化的题检查理解是否稳固。'),
('cmr90329v001493eiel6uxr9j','张思雨','英语课可以采用“读前预测、读中定位、读后复述”的节奏，让学生逐步抓住文章主旨和细节。讲语法时，先比较两种表达在语境中的差异，再总结规则，避免只记术语。写作训练从一句话写准确开始，逐渐扩展到段落的衔接与完整性。对基础薄弱的学生，优先抓高频词和常见句型；对已有基础的学生，则增加独立表达的机会。'),
('cmrahmtx1015312ivbh8ugl58','徐家茹','化学课尤其重视“看到什么、说明什么、还缺少什么证据”这条思路。实验题可先读装置和操作顺序，再分析变量控制与现象解释；推断题则把每个条件写在对应物质或反应旁，减少遗漏。课堂会将易混概念放在同一张对比表里，帮助学生分清性质、用途和反应条件。练习之后回到错因，判断是概念不清还是审题失误。'),
('cmsfsdzse0fw2rx2r7fnwrhsg','朱梦','面对不同学科和不同基础的学生，课堂重点是先确定当前最需要解决的一个问题。数学可用数据和图形帮助学生看见规律；语文可从文本证据引导表达；生物与化学则用过程图梳理前后关系。讲解后留出独立作答时间，不以“听懂了”代替“会做了”。反馈尽量具体到某一类题、某一步推理或某一种表达方式，让下一次练习有明确方向。'),
('cmr7t9qj000045covcufimgo2','李佳瑶','数学课堂可先让学生用自己的话复述题意，再通过画图、列式和验证把思路落到纸面；语文课堂则鼓励先指出原文依据，再组织完整回答。面对相似题型，不只示范一种做法，也会比较方法之间的适用条件。对学生的反馈重视“已掌握什么、还差哪一步”，让作业和复习围绕真实薄弱点展开，逐渐减少会听不会做的情况。'),
('cmr8ulaaf000693eidhi8y5q4','李佳蕊','语文课不把阅读题讲成固定模板，而是先带学生辨认叙述线索、情感变化和题目要求。回答问题时要求观点能在文本中找到依据，再练习把依据转化为简洁、完整的语言。作文训练关注选材是否贴题、段落是否有层次，修改时优先处理结构问题，再打磨字句。这样的课堂更重视阅读后的思考过程，让学生知道答案是如何形成的。'),
('cmp8f7zr3000nappdsz9zd75x','李元林','讲解数学、物理和化学时，可以先把题目归入概念、模型或实验信息三类，再确定切入点。对学生常见的“公式记得住却不会用”，会先检查条件是否满足，而不是马上代入数字。课堂鼓励学生讲出不同解法各自依赖的前提，并在结果出来后回看单位、数量级和逻辑。课后训练以典型错题的变式为主，帮助学生把方法迁移到新情境。'),
('cmp8f56e3000happdveolclp7','李博航','课堂风格偏向用图像和真实问题建立直觉，再把直觉转换成严谨的数学或物理表达。讲力学时先明确研究对象和作用过程；讲数学时先分析变量关系，再选择运算方式。遇到学生想直接套公式，会追问公式从哪里来、什么时候不能用。练习通过改变条件而不是反复更换数字，检验学生是否真正掌握模型边界。'),
('cmr8upujf000e93eiy5dzcgjl','李文泽','化学教学可从一组有联系的实验或反应出发，让学生先观察、作出推测，再用已有知识解释。对于方程式书写，不只检查配平，也会追问反应条件和物质状态。遇到多步骤推断题，鼓励学生把证据逐条标注，发现矛盾时回到原题修正假设。课堂结束以简短的知识回顾和错因归类收束，让学生明确下一次复习应先解决什么。'),
('cmrai33jw01m712iv1nml3irf','李木夕','英语课可以用简短对话或文章片段引出新词和句型，先让学生理解表达意图，再归纳语法形式。阅读题重视证据定位和干扰项辨析，写作则从信息完整、时态一致和句间衔接三个方面逐步修改。对学生口头表达中的错误，可先保护表达意愿，再选择最影响理解的部分进行纠正。希望学生逐渐敢于使用英语，而不只会在试卷上选答案。'),
('cmp8f6c4w000kappdsrj6lmp7','杨则石','理科课堂倾向于先搭建“对象、条件、规律、结论”的解题骨架，再让学生独立填入关键步骤。机械工程背景适合借助运动、受力等直观场景解释物理模型，但不会用复杂背景替代基础知识。对多学科综合题，会提醒学生分清数学工具与学科概念各自的作用。练习后通过反问和复盘定位卡点，避免学生只记住教师演示的顺序。'),
('cms23vgx700008wgol0sqvb2g','毛博远','应用数学背景使课堂更重视问题如何抽象成关系。讲新内容时，可先用熟悉的简单题建立直觉，再逐步增加条件，让学生看到方法为何需要调整。物理和化学题目中涉及计算的部分，会特别提示量纲、边界和结果合理性。学生作答后优先讨论思路而不是只看对错，把错误作为识别概念缺口的线索，再安排少量有针对性的变式题。'),
('cmr8zxvqn001093ei2cr5uck4','牛钰丹','物理课可以从现象、受力或能量变化切入，先让学生画出过程，再选择对应规律；数学课则强调从条件推到结论的每一步都有依据。对容易混用的公式，课堂会并列比较使用条件，而不是让学生机械记忆。练习安排注重独立思考时间，教师讲解之后再给一道条件变化的题，让学生自己判断方法是否仍然适用。'),
('cmr7tklzn00095cov8ikq0pte','王天宇','理科课堂可先让学生描述题目中的现象，再追问造成现象的原因。物理题通过示意图还原过程，化学题通过实验步骤和反应条件寻找证据。讲解时会把容易跳过的中间环节展开，让学生知道结论如何得到；练习时则逐步减少提示，观察学生是否能够独立完成。复盘不只记录错题名称，还记录是概念、计算还是审题出了问题。'),
('cms4mure60dse8wgo7uofnz8f','王怡烁','语言课可以从“先理解，再表达，最后修订”三个环节组织课堂。英语阅读鼓励学生辨认句子之间的逻辑，语文阅读则引导学生抓住作者立场和关键细节。写作练习会先处理内容是否切题，再看句式和措辞是否准确；学生完成初稿后，通过具体问题引导其自主修改，而不是直接给出一篇标准范文。这样的训练旨在提高表达的清晰度。'),
('cmr8ukeib000293eikk4xkn03','王田雪','生物课适合利用结构图、流程图和对比图帮助学生理解生命过程，避免把连续的变化记成孤立名词。物理课则引导学生先说明研究对象、运动或变化过程，再决定使用哪个公式。课堂提问从“是什么”逐步走向“为什么”和“如果条件改变会怎样”，让学生有机会暴露理解偏差。练习后回到图示与语言解释，检验是否真正形成概念。'),
('cmp9n6ork0000hueote2shsil','白婼鑫','理科讲解可采用“先判断模型、再整理信息、最后运算”的顺序。物理题重视图像与单位，化学题重视实验现象和反应条件；对相似题的区别，会让学生主动指出关键条件发生了什么变化。课堂练习不仅检查答案，也关注步骤中是否存在跳跃推理。若学生连续错在同一环节，就回到概念层面重新说明，再用小题验证。'),
('cmp8ecgtc000i2m5ehdt47ul4','胡思同','课堂可以保持轻松但不松散的节奏，用贴近生活的例子引出难点，再把讨论收束到准确的学科表达。讲理科时鼓励学生先提出猜想、说出依据，再一起检验是否成立；讲英语时则增加短句表达和语境替换。对学生的提问先找出其已经理解的部分，再补上缺失的关键一步。课堂的趣味性应服务于知识掌握，而不是代替有效练习。'),
('cmp8f3vhe000eappdxmz8v5c5','苏智博','课堂适合把复杂问题拆成若干可以验证的小判断。数学题先区分条件与目标，物理题先画模型，化学题先查证反应或实验线索；每一步都要求说明依据。遇到同一道题存在不同解法时，可以比较它们的效率和适用范围，让学生选择更稳妥的路径。对计算机背景所带来的逻辑优势，重点体现在检查推理漏洞，而不是增加不必要的术语。'),
('cmrf32hxe0002gymq3u6q5i3w','苏琳曼','英语课堂可采用语篇带动词汇和语法的方式，让学生先理解一段话在说什么，再分析句子为什么这样写。阅读训练关注篇章结构、指代关系和作者意图；写作训练通过改写与扩写逐步提升准确性。对错误答案不只指出“错”，还会比较干扰项与原文的差别。学生能讲出选择依据、能把新词用于自己的句子，才算完成一次有效练习。'),
('cmtmhuzu10003gfuaj57ghn1o','范芳菲','多学科课程需要把节奏控制在学生能够独立跟上的范围内。英语部分可用短文和对话建立语境，数学部分通过画图、列表理清数量关系，化学部分则先分辨实验条件与现象。对于学生回答较慢的情况，先给思考时间，再用逐级提示帮助其找到切入点。课后练习按最需要巩固的一个知识点安排，避免一次布置过多不同类型的任务。'),
('cms5e3iis0fmi8wgomh3o59h6','董士甜','化学课可用实验顺序串起知识点：先看操作目的，再分析观察结果，最后解释反应原理；物理课则从变化过程和受力条件建立模型。遇到需要记忆的内容，会区分必须准确记住的事实与可以通过规律推导的结论。课堂中给学生留出解释现象的机会，发现概念混淆时及时回到具体例子。练习以能否独立说明原因作为重要检查点。'),
('cmp8f8sbn000qappd0hzjj3k1','袁浩东','授课时可以把电子信息专业中的条理化分析用于数学和物理题目，帮助学生分清输入条件、求解过程和最终结论。英语课则更关注词句在篇章中的具体作用，避免只背单词表。对跨学科课程，会提前界定本节课最核心的学习目标，再安排少量能够当堂检验的练习。反馈尽量指出下一次最值得先改进的一个动作，让学生知道从哪里开始。'),
('cmr8un9cy000a93ei6jexlpq7','赵依梦','英语课堂可从学生熟悉的话题进入阅读，再通过段落主旨、细节证据和句间逻辑三个层次逐步加深。词汇讲解不仅给出中文意思，也会比较搭配和语气；语法讲解尽量放回完整句子。写作练习先明确读者和表达目的，再检查内容组织与语言准确性。遇到学生不敢开口时，可从短句复述开始，让表达任务有清楚、可完成的起点。'),
('cms23wpb400058wgoacftgdok','陈佳丽','英语教学可以兼顾语言知识和实际使用。阅读课先让学生判断文章结构，再逐句处理影响理解的长难句；词汇课通过同义替换和语境比较减少机械记忆。写作时鼓励先列要点，再形成段落，最后集中检查时态、主谓一致与衔接。对基础练习中的错误，会区分偶然笔误和反复出现的知识缺口，用不同方式处理，避免无效重复。'),
('cmp8f1djy000bappd21jdet98','陈晓茹','课堂提问可以从“你观察到什么”进入，再追问“依据在哪里、还有没有别的解释”。语文、英语重视文本证据与表达的严谨性；政治、历史、地理和生物则重视概念之间的因果、时间或空间关系。面对记忆量较大的内容，可用主题线索和比较表帮助学生组织信息。练习中鼓励学生讲清观点形成的过程，而不是照搬一套看似万能的答题句式。'),
('cmp8f0hkw0008appdry5o0vr2','陈晓莉','课堂安排可以兼顾知识学习和学生的接受节奏：先用低门槛问题确认基础，再逐步提高任务难度。英语与语文练习中多关注学生是否敢于表达、能否把想法说完整；生物练习则通过图示和复述检查理解。反馈尽量描述具体行为，例如定位依据是否准确、概念是否混淆，而不是用笼统评价给学生贴标签。这样更利于学生知道下一步怎样调整。'),
('cmp8fcqyb000tappd8ppnayim','韩双双','生物课可以从一个生命现象入手，逐步串联结构、功能与调控过程，再让学生用图解复述；化学课则用实验事实支撑概念和反应规律。对于看似会背、却不会解释的知识点，会通过“条件改变后会怎样”的提问检验理解。练习不只追求做完，更关注学生能否解释选项差别和错误原因。课后复习可围绕一张知识关系图继续补充。'),
('cmp8ea70c000f2m5esiqk018e','马韶锟','数学和物理课可以借助工程问题中的约束意识，让学生先判断哪些条件真正有用，再决定如何列式。讲解时尽量把抽象关系画出来，帮助学生看清变量如何相互影响。对于计算题，除结果外还检查单位、符号和合理范围；对于综合题，则训练分段处理的能力。练习后通过条件变式判断学生掌握的是方法，还是只记住了原题的数字。');
